  (* [comment removed for export] *)
  Lemma psc_Ae : forall regs m (s pix cm : Z) (v : pixv) (cv : cmapv) (ret : word),
    (32 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pix)%Z -> PIXat (FR3 m s ret (getr regs 8) (getr regs 9)) pix v -> p_cmap v = cm -> (1 <= cm)%Z ->
    CMAPat (FR3 m s ret (getr regs 8) (getr regs 9)) cm cv -> (c_n cv < c_nalloc cv)%Z ->
    rdn SEGS (FR3 m s ret (getr regs 8) (getr regs 9)) (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) ->
    rdn SEGS (FR3 m s ret (getr regs 8) (getr regs 9)) (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    rdn SEGS (FR3 m s ret (getr regs 8) (getr regs 9)) (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 ret) ->
    rdn SEGS (FR3 m s ret (getr regs 8) (getr regs 9)) (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 (getr regs 8)) ->
    rdn SEGS (FR3 m s ret (getr regs 8) (getr regs 9)) (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 (getr regs 9)) ->
    store_ok SEGS m (Z_to_bv 64 (s - 32)) 32 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pix ->
    exists regs',
      msteps SEGS (mkst regs (0x6e520 : word) m rom) (mkst regs' (0x6304c : word) (FR3 m s ret (getr regs 8) (getr regs 9)) rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 8 = getr regs 8 /\ getr regs' 9 = getr regs 9
      /\ getr regs' 10 = Z_to_bv 64 0x1d565 /\ getr regs' 11 = Z_to_bv 64 0x14ad3 /\ getr regs' 12 = Z_to_bv 64 1
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 12]%list) regs regs'.
Proof.
